public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int Q = sc.nextInt();
    boolean[] hasTooth = new boolean[N + 1];

    // Initialize all holes to have teeth
    for (int i = 1; i <= N; i++) {
        hasTooth[i] = true;
    }

    // Process each treatment
    for (int i = 0; i < Q; i++) {
        int T = sc.nextInt();
        hasTooth[T] = !hasTooth[T]; // Toggle the tooth presence
    }

    // Count the number of holes with teeth
    int count = 0;
    for (int i = 1; i <= N; i++) {
        if (hasTooth[i]) {
            count++;
        }
    }

    // Print the result
    System.out.println(count);
}
